import{_ as t,o as e,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"RWX Storage for Container Orchestrators with CephFS and Manila - Tom Barron, Red Hat","description":"","frontmatter":{"title":"RWX Storage for Container Orchestrators with CephFS and Manila - Tom Barron, Red Hat","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["CephFS","Container Orchestration","OpenStack Manila","Kubernetes","Storage Integration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/RWX_Storage_for_Container_Orchestrators_with_CephFS_and_Manila_-_Tom_Barron_Red_Hat.md","filePath":"posts/2019/RWX_Storage_for_Container_Orchestrators_with_CephFS_and_Manila_-_Tom_Barron_Red_Hat.md","lastUpdated":1780459816000}'),o={name:"posts/2019/RWX_Storage_for_Container_Orchestrators_with_CephFS_and_Manila_-_Tom_Barron_Red_Hat.md"};function l(i,a,s,_,p,h){return e(),r("div",null,[...a[0]||(a[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年5月24日</p><p><strong>会议地点</strong>： [请填写会议地点]</p><p><strong>参会人员</strong>： Tom Barron（红帽下游项目Kim团队负责人）、Robert Vacek（CERN实习生）、James Blair等</p><p><strong>会议主题</strong>： OpenStack Manila与容器编排的集成，特别是针对Ceph文件系统（CephFS）的读写多故事（WX）存储。</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Tom Barron介绍了自己的背景和目前的工作，包括作为红帽下游项目Kim团队负责人的角色。</li><li>突出了OpenStack Manila在提供可扩展存储基础设施、选择自由和多云租户方面的优势。</li></ul></li><li><p><strong>OpenStack与容器编排</strong>：</p><ul><li>讨论了OpenStack和Kubernetes等容器编排工具之间的差异，以及如何为应用开发者提供更便捷的基础设施服务。</li><li>指出应用开发者使用OpenStack时需要具备一定的系统管理员技能。</li></ul></li><li><p><strong>WX存储</strong>：</p><ul><li>Tom介绍了Kubernetes中的WX存储概念，即读写多故事存储，允许多个应用程序同时写入同一个文件系统。</li><li>强调了CephFS在实现WX存储方面的优势，并讨论了CephFS与Kubernetes CSI接口的集成。</li></ul></li><li><p><strong>Manila与CephFS</strong>：</p><ul><li>介绍了Manila如何支持CephFS，包括通过NFS前端和本地接口。</li><li>讨论了即将到来的Manila CSI工作，以及如何将更多功能暴露给容器编排工具。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>CERN的Robert Vacek正在开发Manila CSI插件，红帽团队将进行集成测试和验证。</li><li>计划使用Ansible playbook在OpenStack环境中部署Manila和CephFS。</li><li>探索在Kubernetes环境中运行Ceph和Ganesha服务。</li></ul></li></ol><p><strong>决定事项</strong>：</p><ul><li>红帽团队将继续推动Manila CSI插件的开发和集成。</li><li>与CERN合作，进行集成测试和验证。</li><li>探索在Kubernetes环境中运行Ceph和Ganesha服务。</li></ul><p><strong>后续行动</strong>：</p><ul><li>红帽团队将发布Ansible playbook，以便用户可以在OpenStack环境中部署Manila和CephFS。</li><li>与其他感兴趣的开发者合作，共同推动Manila和CephFS的发展。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中还讨论了CephFS的快照支持、存储扩展和拓扑感知等。</li><li>会议纪要中保留了计算机科学/CEPH领域英文原文的关键词，以保持原文的专业性。</li></ul>',13)])])}const C=t(o,[["render",l]]);export{g as __pageData,C as default};
